// Writes src/ui/styles.generated.ts from src/ui/styles/*.css: the stylesheet text as plain
// string constants, so it loads anywhere (Vite config bundling, tsc output, Node tests) without
// a CSS loader. Run after editing a sheet: `node scripts/gen-ui-styles.mjs`.
// test/ui/styles.test.ts fails while the generated file is out of date.
import fs from 'node:fs'

const dir = new URL('../src/ui/styles/', import.meta.url)
const names = fs
  .readdirSync(dir)
  .filter((name) => name.endsWith('.css') && name !== 'index.css')
  .sort()
const key = (name) => name.replace('.css', '').replace(/-(\w)/g, (_, c) => c.toUpperCase())
let out = '// Generated by scripts/gen-ui-styles.mjs from src/ui/styles/*.css. Do not edit.\n'
for (const name of names) {
  out += `export const ${key(name)} = ${JSON.stringify(fs.readFileSync(new URL(name, dir), 'utf8'))}\n`
}
fs.writeFileSync(new URL('../src/ui/styles.generated.ts', import.meta.url), out)
